        ["browser.navigate"] = new("browser.navigate", BrowserFeature.Navigate, "core", ToolEffect.ReadOnly, """{"type":"object","additionalProperties":false,"properties":{"operation":{"type":"string","enum":["goto","back","forward","reload"]},"url":{"type":"string","maxLength":2048}},"required":[]}"""),
